    /// The caller-safe message. Static for every case except the budget refusal, which names the
    /// period and the reset instant (D8) — never a count and never the org id.
    fn message(self) -> String {
        match self {
            GatewayError::BudgetExhausted { resets_at_unix, period } => match DateTime::<Utc>::from_timestamp(resets_at_unix, 0) {
                Some(instant) => format!(
                    "The organization token budget for {} is used up. It resets at {}.",
                    period.label_at_reset(resets_at_unix),
                    instant.to_rfc3339_opts(SecondsFormat::Secs, true)
                ),
                // An instant outside chrono's range is a corrupt record: name no period, no instant.
                None => self.parts().4.to_owned(),
            },
            other => other.parts().4.to_owned(),
        }
    }

    /// Whether a client should retry (spec D4). `true` ONLY for transient dependency failures.
    /// The two internal cases are `Unknown` rather than `false`: the gateway cannot tell a
    /// transient fault from a bug, and a confident `false` there would be worse than the
    /// status-class guess this replaces.
    pub fn retryable(self) -> Retryable {
        match self {
            Self::IamUnavailable | Self::UpstreamUnavailable | Self::UpstreamTimeout | Self::RateLimited { .. } => Retryable::Yes,
            Self::Internal | Self::MissingScope | Self::ToolInterceptionMalformedResponse => Retryable::Unknown,
            Self::MissingBearer
            | Self::InvalidCredential
            | Self::InvalidDpopProof
            | Self::AuthzDenied
            | Self::BadRequestBody
            | Self::InvalidRequestSchema
            | Self::RequestTooLarge
            | Self::StreamingDisabled
            | Self::InvalidOrgHeader
            GatewayError::from(LimitRefusal::BudgetExhausted {
                period: BudgetPeriod::Daily,
                resets_at_unix: NOV_1
            }),
            GatewayError::BudgetExhausted {
                resets_at_unix: NOV_1,
                period: BudgetPeriod::Daily
            }
        );
        assert_eq!(GatewayError::from(LimitRefusal::Unscoped), GatewayError::Internal, "D2/Q11: fail-closed as 500 internal");
    }

    #[tokio::test]
    async fn only_the_two_refusals_carry_x_should_retry() {
        use strum::IntoEnumIterator;
        for err in GatewayError::iter() {
            let has = err.into_response().headers().contains_key("x-should-retry");
            assert_eq!(has, matches!(err, GatewayError::RateLimited { .. } | GatewayError::BudgetExhausted { .. }), "{err:?}");
        }
    }

    /// SMA-700 § 4.10: the envelope of a refused DPoP proof. `status()` is what the middleware
    /// reads to decide on the challenge.
    #[tokio::test]
    async fn an_invalid_dpop_proof_is_a_401_envelope() {
        let resp = GatewayError::InvalidDpopProof.into_response();
        assert_eq!(resp.headers()["paigasus-retryable"], "false");
        assert!(resp.headers().get("www-authenticate").is_none(), "IntoResponse adds no challenge; the middleware does");
        let body = body_json(resp).await;
        assert_eq!(body["error"]["type"], "invalid_request_error");
        assert_eq!(body["error"]["code"], "invalid-dpop-proof");
        assert_eq!(body["error"]["message"], "Invalid DPoP proof.");
        assert!(body["error"]["param"].is_null());
        assert_eq!(GatewayError::InvalidDpopProof.status(), StatusCode::UNAUTHORIZED);
        assert_eq!(GatewayError::RateLimited { retry_after_secs: 1 }.status(), StatusCode::TOO_MANY_REQUESTS);
    }

    #[tokio::test]
    async fn each_case_maps_to_its_bound_status() {
        assert_eq!(GatewayError::MissingBearer.into_response().status(), StatusCode::UNAUTHORIZED);
        assert_eq!(GatewayError::InvalidCredential.into_response().status(), StatusCode::UNAUTHORIZED);
        assert_eq!(GatewayError::InvalidDpopProof.into_response().status(), StatusCode::UNAUTHORIZED);
        assert_eq!(GatewayError::AuthzDenied.into_response().status(), StatusCode::FORBIDDEN);
        assert_eq!(GatewayError::MissingScope.into_response().status(), StatusCode::INTERNAL_SERVER_ERROR);
        assert_eq!(GatewayError::IamUnavailable.into_response().status(), StatusCode::SERVICE_UNAVAILABLE);
        assert_eq!(GatewayError::Internal.into_response().status(), StatusCode::INTERNAL_SERVER_ERROR);
        assert_eq!(GatewayError::BadRequestBody.into_response().status(), StatusCode::BAD_REQUEST);
        assert_eq!(GatewayError::InvalidRequestSchema.into_response().status(), StatusCode::BAD_REQUEST);
        assert_eq!(GatewayError::RequestTooLarge.into_response().status(), StatusCode::PAYLOAD_TOO_LARGE);
        assert_eq!(GatewayError::UpstreamUnavailable.into_response().status(), StatusCode::BAD_GATEWAY);
        assert_eq!(GatewayError::UpstreamTimeout.into_response().status(), StatusCode::GATEWAY_TIMEOUT);
        assert_eq!(GatewayError::StreamingDisabled.into_response().status(), StatusCode::BAD_REQUEST);
        assert_eq!(GatewayError::InvalidOrgHeader.into_response().status(), StatusCode::BAD_REQUEST);
        assert_eq!(GatewayError::OrgRequired.into_response().status(), StatusCode::BAD_REQUEST);
        assert_eq!(GatewayError::RateLimited { retry_after_secs: 1 }.into_response().status(), StatusCode::TOO_MANY_REQUESTS);
        assert_eq!(
            GatewayError::BudgetExhausted {
                resets_at_unix: 0,
                period: BudgetPeriod::Monthly
            }
            .into_response()
            .status(),
            StatusCode::TOO_MANY_REQUESTS
        );
    }

    #[tokio::test]
    async fn openai_error_maps_timeout_to_504_and_the_rest_to_502() {
        // A real `reqwest::Error` has no public constructor; wrap a genuine one (fresh per variant,
        // since `reqwest::Error` is not `Clone`) and assert the mapping. The request-time
        // classification INTO these variants is G6's concern.
        assert_eq!(GatewayError::from(OpenAiError::Timeout(dead_port_error().await)), GatewayError::UpstreamTimeout);
        assert_eq!(GatewayError::from(OpenAiError::Connect(dead_port_error().await)), GatewayError::UpstreamUnavailable);
        assert_eq!(GatewayError::from(OpenAiError::Transport(dead_port_error().await)), GatewayError::UpstreamUnavailable);
        assert_eq!(GatewayError::from(OpenAiError::Build(dead_port_error().await)), GatewayError::UpstreamUnavailable);
        assert_eq!(
            GatewayError::from(OpenAiError::CaBundle {
                path: "/x".to_string(),
                source: "boom".into()
            }),
            GatewayError::UpstreamUnavailable
        );
    }

    /// Produce a genuine `reqwest::Error` (no public constructor) by dialing an unroutable port.
    async fn dead_port_error() -> reqwest::Error {
        reqwest::Client::new()
            .get("http://127.0.0.1:1")
            .timeout(std::time::Duration::from_millis(50))
            .send()
            .await
            .expect_err("connection to a dead port fails")
    }

    #[tokio::test]
    async fn body_is_the_openai_envelope_shape() {
        let body = body_json(GatewayError::InvalidCredential.into_response()).await;
        // Exact OpenAI shape: a single `error` object with message/type/param/code.
        let err = body.get("error").expect("envelope has a top-level `error` object");
        assert!(err.get("message").and_then(|m| m.as_str()).is_some_and(|m| !m.is_empty()));
        assert_eq!(err["type"], "invalid_request_error");
        assert_eq!(err["code"], "invalid-api-key");
        assert!(
            err["param"].is_null(),
            "InvalidCredential names nothing at fault, so param is null (StreamingDisabled, InvalidOrgHeader and OrgRequired set it)"
        );
    }

